def is_permutation(nums):
    n = len(nums)
    ok = True
    for x in nums:
        v = abs(x)
        if v < 1 or v > n or nums[v - 1] < 0:
            ok = False
            break
        nums[v - 1] = -nums[v - 1]
    for i in range(n):
        nums[i] = abs(nums[i])
    return ok

code.java:
static boolean isPermutation(int[] nums) {
    int n = nums.length;
    boolean ok = true;
    for (int i = 0; i < n; i++) {
        int v = Math.abs(nums[i]);
        if (v < 1 || v > n || nums[v - 1] < 0) {
            ok = false;
            break;
        }
        nums[v - 1] = -nums[v - 1];
    }
    for (int i = 0; i < n; i++) nums[i] = Math.abs(nums[i]);
    return ok;
}

